import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_elements
) {
    // Each thread handles one element in the batch
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= batch_size * spatial_elements) return;

    // Calculate the starting index for this batch element
    int batch_idx = idx / spatial_elements;
    int spatial_idx = idx % spatial_elements;

    // Compute sum of squares for this batch element
    float sum_sq = 0.0f;

    // Iterate over all features for this spatial position
    for (int f = 0; f < num_features; ++f) {
        int input_idx = batch_idx * num_features * spatial_elements + f * spatial_elements + spatial_idx;
        half val = input[input_idx];
        float val_f = __half2float(val);
        sum_sq += val_f * val_f;
    }

    // Compute RMS
    float rms = sqrtf(sum_sq / num_features + eps);

    // Normalize and write back
    for (int f = 0; f < num_features; ++f) {
        int input_idx = batch_idx * num_features * spatial_elements + f * spatial_elements + spatial_idx;
        int output_idx = input_idx;
        half val = input[input_idx];
        float val_f = __half2float(val);
        float normalized = val_f / rms;
        output[output_idx] = __float2half(normalized);
    }
}

// Optimized version using shared memory for better performance
__global__ void rms_norm_kernel_optimized(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_elements
) {
    extern __shared__ float shared_data[];

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int tid = threadIdx.x;

    if (idx >= batch_size * spatial_elements) return;

    int batch_idx = idx / spatial_elements;
    int spatial_idx = idx % spatial_elements;

    // Load data into shared memory and compute sum of squares
    float sum_sq = 0.0f;

    for (int f = 0; f < num_features; ++f) {
        int input_idx = batch_idx * num_features * spatial_elements + f * spatial_elements + spatial_idx;
        half val = input[input_idx];
        float val_f = __half2float(val);
        sum_sq += val_f * val_f;
    }

    // Compute RMS
    float rms = sqrtf(sum_sq / num_features + eps);

    // Normalize and write back
    for (int f = 0; f < num_features; ++f) {
        int input_idx = batch_idx * num_features * spatial_elements + f * spatial_elements + spatial_idx;
        int output_idx = input_idx;
        half val = input[input_idx];
        float val_f = __half2float(val);
        float normalized = val_f / rms;
        output[output_idx] = __float2half(normalized);
    }
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="rms_norm_cuda",
        cpp_sources=[],
        cuda_sources=cuda_source,
        functions=["rms_norm_kernel", "rms_norm_kernel_optimized"],
        verbose=False
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, num_features: int, eps: float = 1e-5):
            super().__init__()
            self.num_features = num_features
            self.eps = eps

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            # Ensure input is float16
            if x.dtype != torch.float16:
                x = x.to(torch.float16)

            batch_size, num_features, *spatial_dims = x.shape
            spatial_elements = 1
            for dim in spatial_dims:
                spatial_elements *= dim

            # Prepare output tensor
            output = torch.empty_like(x)

            # Launch kernel
            grid_size = (batch_size * spatial_elements + 255) // 256
            block_size = 256

            # Use optimized kernel
            module.rms_norm_kernel_optimized(
                x.data_ptr(),
                output.data_ptr(),
                self.eps,
                batch_size,
                num_features,
                spatial_elements,
                grid=(grid_size,),
                block=(block_size,)
            )

            return output

    return ModelNew

ModelNew = compile_and_run()
